#!/bin/sh
# lis: 2 annotations, legfed_v1_0 families.
# Generated by lis-autocontent populate-gcv. redis_loader runs this only while Redis
# is empty, saving after each load.

set -o errexit -o pipefail

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
inputs=/docker-entrypoint-initdb.d/gcv_inputs.py

echo Vigna/unguiculata/annotations/IT97K-499-35.gnm1.ann1.zb5D
python -u "$inputs" chromosomes \
  https://data.legumeinfo.org/Vigna/unguiculata/genomes/IT97K-499-35.gnm1.QnBW/vigun.IT97K-499-35.gnm1.QnBW.genome_main.fna.gz.fai \
  "$work/chromosomes.gff3" \
  --rename gnm1 gnm1.ann1
python -u "$inputs" genes \
  https://data.legumeinfo.org/Vigna/unguiculata/annotations/IT97K-499-35.gnm1.ann1.zb5D/vigun.IT97K-499-35.gnm1.ann1.zb5D.gene_models_main.gff3.gz \
  "$work/genes.gff3" \
  --rename gnm1 gnm1.ann1
python -u -m redis_loader --load-type append gff \
  --genus Vigna \
  --species unguiculata \
  --strain IT97K-499-35 \
  --chromosome-gff "$work/chromosomes.gff3" \
  --gene-gff "$work/genes.gff3" \
  --gfa https://data.legumeinfo.org/Vigna/unguiculata/annotations/IT97K-499-35.gnm1.ann1.zb5D/vigun.IT97K-499-35.gnm1.ann1.zb5D.legfed_v1_0.M65K.gfa.tsv.gz

echo Vigna/unguiculata/annotations/IT97K-499-35.gnm1.ann2.FD7K
python -u "$inputs" chromosomes \
  https://data.legumeinfo.org/Vigna/unguiculata/genomes/IT97K-499-35.gnm1.QnBW/vigun.IT97K-499-35.gnm1.QnBW.genome_main.fna.gz.fai \
  "$work/chromosomes.gff3"
python -u -m redis_loader --load-type append gff \
  --genus Vigna \
  --species unguiculata \
  --strain IT97K-499-35 \
  --chromosome-gff "$work/chromosomes.gff3" \
  --gene-gff https://data.legumeinfo.org/Vigna/unguiculata/annotations/IT97K-499-35.gnm1.ann2.FD7K/vigun.IT97K-499-35.gnm1.ann2.FD7K.gene_models_main.gff3.gz \
  --gfa https://data.legumeinfo.org/Vigna/unguiculata/annotations/IT97K-499-35.gnm1.ann2.FD7K/vigun.IT97K-499-35.gnm1.ann2.FD7K.legfed_v1_0.M65K.gfa.tsv.gz
